    private static func icon(
        _ id: String,
        _ category: ClearframeIconCategory,
        _ x: Double,
        _ y: Double,
        _ width: Double,
        _ height: Double,
        _ markup: String
    ) -> ClearframeIcon {
        ClearframeIcon(
            id: id,
            category: category,
            markup: markup,
            style: .stickies,
            box: VectorBox(x: x, y: y, width: width, height: height)
        )
    }
